def find_neighbors(r, c, grid):
    neigh = []
    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        nr, nc = r+dr, c+dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            neigh.append((nr, nc, grid[nr][nc]))
    return neigh

def dominated_by(r, c, target, grid):
    """Check if position (r,c) is dominated by 'target' from ALL non-background directions"""
    # Check top row
    for nr in range(r-1, -1, -1):
        val = grid[nr][c]
        if val != 0 and val != 9:
            if val == target:
                return True  # Found target from top
            break
    # Check bottom row
    for nr in range(r+1, len(grid)):
        val = grid[nr][c]
        if val != 0 and val != 9:
            if val == target:
                return True  # Found target from bottom
            break
    # Check left column
    for nc in range(c-1, -1, -1):
        val = grid[r][nc]
        if val != 0 and val != 9:
            if val == target:
                return True  # Found target from left
            break
    # Check right column
    for nc in range(c+1, len(grid[0])):
        val = grid[r][nc]
        if val != 0 and val != 9:
            if val == target:
                return True  # Found target from right
            break
    return False

# Simpler rule based on demo analysis:
# 1. Zeros and background (9) are "transparent" or "neutral"
# 2. Non-background colors at boundaries of one-color regions change to match the region
# 3. Zeros get filled by whatever non-background colors are "dominating" from any direction

def transform_simple1(grid):
    output = [row[:] for row in grid]
    # Single-pass: don't update output in place, always read from input_grid

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            cell = grid[r][c]
            neigh = find_neighbors(r, c, grid)

            if cell == 0:
                # Zero cell: find the dominant neighboring color
                non9_nz = [v for _, _, v in neigh if v not in (0, 9)]
                if non9_nz:
                    cnt = Counter(non9_nz)
                    max_c = max(cnt.values())
                    majority = [k for k, v in cnt.items() if v == max_c]
                    if len(majority) == 1 and max_c >= len(non9_nz) / 2:
                        output[r][c] = majority[0]

                # Fill zeros by scanning adjacent non-background cells
                # Start with checking 4-directional adjacent non-background non-9 cells
                from collections import deque
                queue = deque([(nc, vc) for nc, vc in neigh if grid[nc][vc] != 0 and grid[nc][vc] != 9])

                if queue:
                    all_vals = Counter([grid[nc][vc] for nc, vc in queue])
                    max_count = max(all_vals.values())
                    majority_4 = [k for k, v in all_vals.items() if v == max_count]
                    if len(majority_4) == 1:
                        output[r][c] = majority_4[0]

                # Expand to 2-step neighbors if no direct colored neighbors
                if output[r][c] == 0:
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] != 0 and grid[nr][nc] != 9:
                                output[r][c] = grid[nr][nc]
                                break

        # Pad remaining zeros in the region to background
        rows_with_zeros = [r for r in range(5, 12)]
        cols_with_zeros = [6, 7, 8, 9]
        for r in range(5, 12):
            for c in range(6, 10):
                if output[r][c] == 0:
                    # Check if we have nearby 6, 8, or 4
                    for dr, dc in [(-2,0),(2,0),(0,-2),(0,2)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            val = grid[nr][nc]
                            if val != 0 and val != 9:
                                output[r][c] = val
                                break

    return output

